import sys, socket, struct, threading
sys.path.insert(0, "/workspace/probe")
from dnskit import *

PORT = int(sys.argv[1])

def handler(q):
    r = Response(q)
    r.add_answer("example.com", "A", 300, A("1.2.3.4"))
    return r

def log(proto, data, prefix=b""):
    print(f"[{proto}] PARSED {parse_query(data)}", flush=True)
    print(f"[{proto}] HEX {prefix.hex() + '|' if prefix else ''}{data.hex()}", flush=True)

def udp_loop(s):
    while True:
        try:
            data, addr = s.recvfrom(65535)
            log("udp", data)
            resp = handler(data)
            if resp is not None:
                s.sendto(resp.build(), addr)
        except Exception as e:
            print("[udp error]", e, flush=True)

def tcp_conn(conn):
    try:
        while True:
            hdr = recv_exact(conn, 2)
            if not hdr:
                break
            (length,) = struct.unpack(">H", hdr)
            data = recv_exact(conn, length)
            log("tcp", data, prefix=hdr)
            resp = handler(data)
            if resp is not None:
                b = resp.build()
                conn.sendall(struct.pack(">H", len(b)) + b)
    except Exception:
        pass
    finally:
        conn.close()

def tcp_loop(s):
    while True:
        try:
            conn, _ = s.accept()
            threading.Thread(target=tcp_conn, args=(conn,), daemon=True).start()
        except Exception as e:
            print("[tcp error]", e, flush=True)

u = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
u.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
u.bind(("127.0.0.1", PORT))
t = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
t.setsockopt(socket.SOL_SOCKET, socket.SOCK_REUSEADDR, 1)
t.bind(("127.0.0.1", PORT))
t.listen(5)
threading.Thread(target=udp_loop, args=(u,), daemon=True).start()
threading.Thread(target=tcp_loop, args=(t,), daemon=True).start()
print(f"serving 127.0.0.1:{PORT}", flush=True)
threading.Event().wait()

