import sys, socket, struct, threading
sys.path.insert(0, "/workspace/probe")
from dnskit import *

PORT = int(sys.argv[1])
MODE = sys.argv[2]  # "conns" or "tc"

conn_counter = [0]

def handler_normal(q):
    r = Response(q)
    r.add_answer("example.com", "A", 300, A("1.2.3.4"))
    return r.build()

def handler_tc(q):
    # respond over UDP with TC=1 and no answers
    r = Response(q, tc=1)
    return r.build()

def udp_loop(s):
    while True:
        try:
            data, addr = s.recvfrom(65535)
            print(f"[udp] HEX {data.hex()}", flush=True)
            if MODE == "tc":
                s.sendto(handler_tc(data), addr)
            else:
                s.sendto(handler_normal(data), addr)
        except Exception as e:
            print("[udp error]", e, flush=True)

def tcp_conn(conn, cid):
    try:
        while True:
            hdr = recv_exact(conn, 2)
            if not hdr:
                break
            (length,) = struct.unpack(">H", hdr)
            data = recv_exact(conn, length)
            print(f"[tcp conn#{cid}] HEX {hdr.hex()}|{data.hex()}", flush=True)
            b = handler_normal(data)
            conn.sendall(struct.pack(">H", len(b)) + b)
    except Exception:
        pass
    finally:
        print(f"[tcp conn#{cid}] CLOSED", flush=True)
        conn.close()

def tcp_loop(s):
    while True:
        try:
            conn, _ = s.accept()
            conn_counter[0] += 1
            cid = conn_counter[0]
            print(f"[tcp] ACCEPT conn#{cid}", flush=True)
            threading.Thread(target=tcp_conn, args=(conn, cid), daemon=True).start()
        except Exception as e:
            print("[tcp error]", e, flush=True)

u = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
u.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
u.bind(("127.0.0.1", PORT))
t = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
t.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
t.bind(("127.0.0.1", PORT))
t.listen(5)
threading.Thread(target=udp_loop, args=(u,), daemon=True).start()
threading.Thread(target=tcp_loop, args=(t,), daemon=True).start()
print(f"serving 127.0.0.1:{PORT} mode={MODE}", flush=True)
threading.Event().wait()

